{
  "concepts": [],
  "definitions": [],
  "examples": [],
  "explanations": [
    {
      "topic": {
        "text": "switch statement versus if statement for role-based messages",
        "refs": ["Q0001"]
      },
      "explanation_text": {
        "text": "A switch statement can be used instead of multiple if/else statements to compare a variable (e.g., role) against constant values (e.g., admin, moderator, guest) and execute the matching case block.",
        "refs": ["Q0001"]
      },
      "explanation_type": null
    },
    {
      "topic": {
        "text": "purpose of break statement in a switch block",
        "refs": ["Q0003"]
      },
      "explanation_text": {
        "text": "The break statement exits the switch block after a case has been executed; without it, execution falls through to subsequent case blocks.",
        "refs": ["Q0003"]
      },
      "explanation_type": null
    }
  ],
  "facts": [
    {
      "fact_text": {
        "text": "If role equals \"admin\", the program should print \"you are an admin\".",
        "refs": ["Q0000", "Q0001"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "If role equals \"moderator\", the program should print \"you are a moderator\".",
        "refs": ["Q0000", "Q0002"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "If role matches none of the specified cases, the default case prints \"you are a guest\".",
        "refs": ["Q0000", "Q0002", "Q0003"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "When the switch variable is a string, cases must use string literals; using an integer variable would require numeric case labels.",
        "refs": ["Q0004"]
      },
      "fact_type": null
    }
  ],
  "formulas": [],
  "procedures": [
    {
      "procedure_name": {
        "text": "Implement role-based messaging with a switch statement",
        "refs": ["Q0001"]
      },
      "steps": [
        {
          "text": "Write the switch keyword followed by parentheses containing the variable to test (e.g., role).",
          "refs": ["Q0001"]
        },
        {
          "text": "Open a block with braces and add case clauses for each role value (admin, moderator, etc.), ending each case label with a colon.",
          "refs": ["Q0002"]
        },
        {
          "text": "Inside each case block, add the code to print the appropriate message.",
          "refs": ["Q0002"]
        },
        {
          "text": "Add a break statement after each case (except the final default case) to exit the switch.",
          "refs": ["Q0002", "Q0003"]
        },
        {
          "text": "Optionally add a default case to handle any unmatched role values.",
          "refs": ["Q0002"]
        }
      ],
      "prerequisites": null,
      "outcomes": null,
      "content": {
        "text": "A switch statement evaluates the role variable and executes the matching case block, printing the corresponding message and using break statements to prevent fall‑through.",
        "refs": ["Q0001", "Q0002", "Q0003"]
      }
    }
  ],
